-- BEGIN generated communication-goal lessons (learning-content.json)
-- SOURCE SHA256 communication_path_release=4b0da62552a9c2cace724b0683b78a262e1a0a4ddbccc3f8e2b484d0327a93d7 goal_source_snapshots=16b3246214903b807ee5b579a0db7cbc7773aecb509a19ef2ed99749d1ce1cba
-- Generated. Edit the canonical JSON section and run this generator; do not hand-edit this block.
-- Communication lessons have no scored quiz or JLPT grading. TTS is an explicit browser-speech sentinel.
-- Attribution: JMdict / EDRDG, CC BY-SA 4.0 https://www.edrdg.org/edrdg/licence.html
-- Fails closed: any validator SIGNAL aborts before COMMIT, so the whole block rolls back.
SET NAMES utf8mb4;
DELIMITER //
DROP PROCEDURE IF EXISTS jlas_validate_comm_path_v1//
CREATE PROCEDURE jlas_validate_comm_path_v1()
BEGIN
  IF EXISTS (SELECT 1 FROM content_vocabulary cv JOIN vocabulary_entry v ON v.id=cv.vocabulary_id JOIN content_item ci ON ci.id=cv.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code LIKE 'LP-OWNED-COMM-%' AND v.dictionary_status='HIDDEN') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: a source vocabulary entry is hidden in the canonical dictionary.';
  END IF;
  IF EXISTS (SELECT 1 FROM content_item ci JOIN jlas_comm_expected e ON e.section_id=ci.section_id WHERE ci.order_index>e.items) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale content items remain beyond the generated list; a shorter list needs a migration.';
  END IF;
  IF EXISTS (SELECT 1 FROM grammar_point gp JOIN jlas_comm_expected e ON e.lesson_id=gp.lesson_id WHERE gp.order_index>e.grammar) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale grammar points remain beyond the generated list; a shorter list needs a migration.';
  END IF;
  IF EXISTS (SELECT 1 FROM dialogue_role r JOIN jlas_comm_expected e ON e.lesson_id=r.lesson_id WHERE r.code NOT REGEXP '^ROLE-[0-9]+$' OR CAST(SUBSTRING(r.code,6) AS UNSIGNED)>e.roles) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale dialogue roles remain beyond the generated list; a shorter list needs a migration.';
  END IF;
END//
DELIMITER ;
DROP TEMPORARY TABLE IF EXISTS jlas_comm_expected;
CREATE TEMPORARY TABLE jlas_comm_expected (section_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, lesson_id BIGINT UNSIGNED NOT NULL, items INT UNSIGNED NOT NULL, grammar INT UNSIGNED NOT NULL, roles INT UNSIGNED NOT NULL);
START TRANSACTION;
